/// does real work everywhere below that ceiling; where it cannot, say so, rather than printing
/// one number twice with "up to" between them.
///
/// Compared on the ROUNDED percentages because those are what the player reads — and kept to one
/// short line, because the widget above the fortnight has room for exactly one.
/// </summary>
public static string OddsPreview(double plain, double best)
{
    if (plain <= 0 && best <= 0) return "tonight: nothing at all can come of it";
    if (Math.Round(best * 100.0) <= Math.Round(plain * 100.0))
        return $"tonight: {Percent(plain)} — no gift can raise it higher";
    return $"tonight: {Percent(plain)} plainly, up to {Percent(best)} with the grandest gift";
}

