/// <summary>The stop we are presently at (or the open road-bucket), if any.
/// NEVER PERSISTED: it ALIASES a live element of <see cref="Visits"/>, so serializing it
/// writes that visit a SECOND time and the next load populates the copy back INTO the same
/// instance — reusing its lists and appending them to themselves (the item flood,
/// 2026.08.16). Every computed view on a persisted type must stay ignored for that reason.</summary>
[JsonIgnore]
public JourneyVisit? OpenVisit =>
    Visits.LastOrDefault(v => v != null && v.LeaveDay < 0);

// ... and likewise:
[JsonIgnore]
public IReadOnlyList<JourneyQuest> OpenQuests => ...
[JsonIgnore]
public IReadOnlyList<JourneyQuest> ResolvedQuests => ...
// on JourneyVisit:
[JsonIgnore]
public bool HasAnyDoings => ...

/// <summary>Heals piece-lists doubled by the old OpenVisit round trip (2026.08.16). Rides
/// on the invariant that every write goes through <see cref="JourneyVisit.AddCounted"/>,
/// which merges by name — so a name standing twice in one list is a replayed copy, and the
/// first of them holds the honest count. Dropped, NEVER summed.</summary>
public void DropReplayedLines()
{
    foreach (var v in Visits)
    {
        if (v == null) continue;
        DropRepeatedNames(v.BoughtNotable);
        DropRepeatedNames(v.SoldNotable);
        DropRepeatedNames(v.Recruited);
        DropRepeatedNames(v.LeftInGarrison);
    }
}

private static void DropRepeatedNames(List<string> lines)
{
    if (lines == null || lines.Count < 2) return;
    var seen = new HashSet<string>(StringComparer.Ordinal);
    for (int i = 0; i < lines.Count; i++)
    {
        int cut = lines[i].LastIndexOf(" ×", StringComparison.Ordinal);
        if (seen.Add(cut > 0 ? lines[i].Substring(0, cut) : lines[i])) continue;
        lines.RemoveAt(i);
        i--;
    }
}

