// What a band carries besides its fighters. Both are PLAIN SIGHT, not divination: the game draws
// the hurt and the bound on the band's own nameplate ("+8w +12p") and lists the prisoners — heroes
// by name — in its map tooltip. Only the COUNT is the eye's business.
// wholeArmy mirrors whatever body of men the head-count beside it covers, or the numbers disagree.
private static int WoundedIn(MobileParty p, bool wholeArmy) => wholeArmy
    ? Safe(() => p.Army.TotalManCount - p.Army.TotalHealthyMembers, 0)
    : Safe(() => p.MemberRoster?.TotalWounded ?? 0, 0);

private static int PrisonersIn(MobileParty p, bool wholeArmy) => wholeArmy
    ? Safe(() => (p.Army.LeaderParty.PrisonRoster?.TotalManCount ?? 0)
        + p.Army.LeaderParty.AttachedParties.Sum(x => x.PrisonRoster?.TotalManCount ?? 0), 0)
    : Safe(() => p.PrisonRoster?.TotalManCount ?? 0, 0);

// A count in the eyes' own words, on the SAME Scouting bands as the head-count above. Below the
// middling band no number is given at all — the shapes, not the counts. A count smaller than the
// rounding step is told true: RoundTo floors at its own step, so rounding three would invent ten.
private static string Counted(int n, int eyes, int step)
{
    if (eyes >= 125 || n < step) return n.ToString();
    if (eyes >= 50) return "some " + RoundTo(n, step);
    return string.Empty;
}

